const map=$('#map').getContext('2d');function drawMap(){map.fillStyle='#e1c4d0';map.fillRect(0,0,220,220);const point=(x,z)=>[110+x*3.5,110+z*3.5];map.fillStyle='#a38eb6';map.fillRect(...point(-19,-14),42,35);for(const [p,c] of [[TOSS,'#d78e91'],[CARPET,'#719e92']]){map.fillStyle=c;map.beginPath();map.arc(...point(p.x,p.z),9,0,7);map.fill();}for(const [i,b] of BUTTONS.entries())if(!state.buttons.includes(i)){map.fillStyle='#fff2ad';map.beginPath();map.arc(...point(b.x,b.z),4,0,7);map.fill();}map.fillStyle='#6a5483';map.beginPath();map.arc(...point(state.monster.x,state.monster.z),5,0,7);map.fill();map.fillStyle='#fff8ef';map.strokeStyle='#5c466b';map.beginPath();map.arc(...point(state.x,state.z),4,0,7);map.fill();map.stroke();}
function refreshHud(){const near=nearby(state),sky=weather(state);$('#zone').textContent=sky==='warning'?'The bedtime wind is stirring…':sky==='storm'?'Blanket blizzard!':inFort(state)?'Safe inside the wishing fort':'A little kingdom of cozy';$('#button-count').textContent=`✿ ${state.buttons.length} / 6 buttons`;$('#badge-count').textContent=`${Object.values(state.badges).filter(Boolean).length} / 4 cozy badges`;for(const [id,earned] of Object.entries(state.badges)){$('#badge-'+id).classList.toggle('found',earned);$('#badge-'+id+' .check').textContent=earned?'✓':'○';}
 const action=$('#interact');action.disabled=!!state.ride||!!state.game&&state.game.cooldown>0;action.classList.toggle('ready',!!near&&!state.ride);action.classList.toggle('aim-ready',!!state.game&&throwReady(state));action.querySelector('strong').textContent=state.ride?'A very soft adventure…':near?.name||'Follow a little sparkle';action.querySelector('small').textContent=near?.kind==='throw'?(throwReady(state)?'Mint ring! A lovely moment to throw.':'Wait for the mint ring…'):near?.kind==='tickle'?'Even monsters need a little giggle':near?.kind==='flight'?'One scenic lap. No ticket required.':'Six buttons. Four badges. Lots of blankets.';
 document.body.classList.toggle('playing',!!state.game);document.body.classList.toggle('stormy',sky==='storm');document.body.classList.toggle('busy',!!state.game||!!state.ride);$('#game-banner').hidden=!state.game&&!state.ride;$('#stop-game').hidden=!state.game;$('#jump').disabled=!!state.ride;
 if(state.game){$('#game-eyebrow').textContent='PILLOW TOSS';$('#game-title').textContent=`${state.game.score} / 5 hits · ${Math.ceil(state.game.left)}s`;$('#game-detail').textContent=throwReady(state)?'Mint ring! Throw a pillow now.':'Wait for mint… then throw!';$('#game-progress').style.width=`${state.game.left/40*100}%`;}
 if(state.ride){const flying=state.ride.kind==='flight';$('#game-eyebrow').textContent=flying?'THE MAGIC QUILT EXPRESS':'A SNOOZE SPECIAL DELIVERY';$('#game-title').textContent=flying?'The softest way to fly.':'You’re a blanket burrito!';$('#game-detail').textContent=flying?'Next stop: a wonderfully soft landing.':'No buttons lost. Just a very silly hug.';$('#game-progress').style.width=`${Math.min(100,state.ride.time/(flying?10.7:4.2)*100)}%`;}drawMap();}
const cameraTarget=v(state.x,1.5,state.z),clock=new THREE.Clock();let uiTime=0;
function animate(){requestAnimationFrame(animate);const dt=Math.min(.035,clock.getDelta()),isPaused=paused(),sx=(keys.has('d')?1:0)-(keys.has('a')?1:0)+joy.x,sz=(keys.has('s')?1:0)-(keys.has('w')?1:0)+joy.y;const input=toolInput||{x:sx*Math.cos(yaw)+sz*Math.sin(yaw),z:-sx*Math.sin(yaw)+sz*Math.cos(yaw)};
 if(!isPaused){tick(state,dt,input);effects();}const t=state.time,sky=weather(state),storm=sky==='storm',ride=state.ride;
 const tint=storm?'#9f9bb9':'#d2c4d7';scene.background.lerp(new THREE.Color(tint),1-Math.exp(-dt*1.5));scene.fog.color.copy(scene.background);sunlight.intensity+=( (storm?1:2.3)-sunlight.intensity)*Math.min(1,dt*2);
 astronaut.position.set(state.x,state.y,state.z);astronaut.rotation.set(0,state.yaw,ride?.kind==='burrito'&&!reduced?Math.sin(ride.time*5)*1.1:0);body.visible=ride?.kind!=='burrito';burrito.visible=ride?.kind==='burrito';const moving=!isPaused&&!ride&&Math.hypot(input.x,input.z)>.1;if(moving)walkPhase+=dt*10;limbs.forEach((l,i)=>l.rotation.x=moving?Math.sin(walkPhase+(i<2?0:Math.PI))*.5:0);cape.rotation.x=reduced?0:Math.sin(t*3)*.1;
 const m=state.monster;monster.position.set(m.x,groundHeight(m.x,m.z),m.z);const facing=Math.atan2(state.x-m.x,state.z-m.z);monster.rotation.y+=Math.atan2(Math.sin(facing-monster.rotation.y),Math.cos(facing-monster.rotation.y))*Math.min(1,dt*3);monster.scale.y=m.nap>0?.75:1;monster.position.y+=reduced?0:Math.sin(t*2)*.1;zzz.visible=m.nap>0;monsterName.visible=m.nap===0;mouth.scale.y=m.nap>0?.1:.25;arms.forEach((a,i)=>a.rotation.z=(reduced?0:Math.sin(t*(storm?8:2)+i)*.2));tuft.rotation.z=reduced?0:Math.sin(t*3)*.1;
 const inside=inFort(state)&&!ride;fortMaterials.forEach(m=>{m.opacity=inside?.27:1;m.depthWrite=!inside;});lights.forEach((o,i)=>{o.material.color.set(state.badges.fort?'#ffe99b':'#b3a0ae');o.scale.setScalar(.13*(state.badges.fort?1.1+(reduced?0:Math.sin(t*2+i)*.15):.7));});fortLight.intensity=state.badges.fort?65:0;
 basket.position.x=basketX(t);basket.rotation.z=reduced?0:Math.sin(t*1.15)*.07;aimRing.material.color.set(state.game&&throwReady(state)?'#40bd88':'#f1cf96');aimLabel.visible=!!state.game;target.children[0].scale.setScalar(state.game?1.1:1);tossMat.scale.y=1;
 buttonObjects.forEach(({g,sparkle,i})=>{g.visible=!state.buttons.includes(i);g.position.y=groundHeight(BUTTONS[i].x,BUTTONS[i].z)+1.15+(reduced?0:Math.sin(t*2+i)*.17);g.rotation.y=t*.6;sparkle.rotation.z=t;});springs.forEach((g,i)=>g.scale.y=1+(reduced?0:Math.sin(t*2+i)*.08));windFlags.forEach((f,i)=>f.rotation.y=reduced?0:Math.sin(t*(storm?8:2)+i)*(storm?.35:.08));
 if(ride?.kind==='flight'){flyingQuilt.position.set(state.x,state.y-.12,state.z);flyingQuilt.rotation.y=state.yaw;flyingQuilt.rotation.z=reduced?0:Math.sin(ride.time*2)*.09;}else{flyingQuilt.position.set(CARPET.x,groundHeight(CARPET.x,CARPET.z)+.4+(reduced?0:Math.sin(t*2)*.12),CARPET.z);flyingQuilt.rotation.set(0,-.15,0);}carpetSign.visible=ride?.kind!=='flight';
 for(const p of state.throws){let o=pillowObjects.get(p.id);if(!o){o=pillow(scene,pinkCloth,0,0,0,1.2,.9,.2);pillowObjects.set(p.id,o);}const at=pillowPosition(p);o.position.set(at.x,at.y,at.z);o.rotation.set(p.age*5,p.age*2,0);}for(const [id,o] of pillowObjects)if(!state.throws.some(p=>p.id===id)){o.removeFromParent();o.traverse(c=>{if(c.geometry&&c.geometry!==sphere)c.geometry.dispose();if(c.isLine)c.material.dispose();});pillowObjects.delete(id);}
 for(const [i,o] of windBits.entries()){o.visible=storm&&!reduced;if(o.visible){o.position.set(((t*14+i*3.7)%70)-35,1+(i%7),((i*5.3)%52)-26);o.rotation.set(t+i,t*.7,Math.sin(t+i));}}
 if(!isPaused)for(const p of particles)if(p.life>0){p.life-=dt;p.v.y-=5*dt;p.o.position.addScaledVector(p.v,dt);p.o.rotation.y+=dt*3;p.o.visible=p.life>0;}
 const lead=ride?0:4;const wanted=v(state.x-Math.sin(yaw)*lead,state.y+1.3,state.z-Math.cos(yaw)*lead);cameraTarget.lerp(wanted,1-Math.exp(-dt*5));const d=ride?.kind==='flight'?Math.max(distance,42):distance;camera.position.copy(cameraTarget).add(v(Math.sin(yaw)*Math.cos(pitch)*d,Math.sin(pitch)*d,Math.cos(yaw)*Math.cos(pitch)*d));camera.lookAt(cameraTarget);if((uiTime+=dt)>.1){uiTime=0;refreshHud();}renderer.render(scene,camera);
}
addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<700?56:45;camera.updateProjectionMatrix();});
