if(document.modelContext?.registerTool){const lifecycle=new AbortController(),register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_blanket_world',description:'Read the explorer, blanket activities, buttons, badges, weather, and Snooze.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:readState});register({name:'walk_blanket_world',description:'Walk normally on the quilt along world axes for 0.1 to 3 seconds. Negative z heads toward the fort; positive x toward Pillow Toss. Optionally jump. No teleporting.',inputSchema:{type:'object',properties:{x:{type:'number',minimum:-1,maximum:1},z:{type:'number',minimum:-1,maximum:1},seconds:{type:'number',minimum:.1,maximum:3},jump:{type:'boolean'}},required:['x','z','seconds'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(a){if(paused()||![a.x,a.z,a.seconds].every(Number.isFinite)||Math.abs(a.x)>1||Math.abs(a.z)>1||a.seconds<.1||a.seconds>3)throw new Error('Close menus and use valid movement controls.');if(a.jump)jump(state);toolInput={x:a.x,z:a.z};try{await new Promise(r=>setTimeout(r,a.seconds*1000));}finally{toolInput=null;}return readState();}});addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
